liquid:
{% assign discount_code = '' %}
{% assign api_ease_parameters_json = apiEaseParameters | json %}
{% assign liquid_params_json = '{}' %}
{% if api_ease_parameters_json contains '"liquidParams"' %}
  {% assign liquid_params_json = apiEaseParameters.liquidParams | json %}
{% endif %}
{% if liquid_params_json contains '"code":' %}
  {% assign discount_code = apiEaseParameters.liquidParams.code | default: '' | strip %}
{% endif %}
{% if discount_code == '' %}
{
  "ok": false,
  "found": false,
  "message": "Enter a discount code."
}
{% else %}
{% call {
  "requestId": "lookup-shopify-discount-code-admin-graphql",
  "bodyEmbedded": {
    "variables": {
      "code": {{ discount_code | json }}
    }
  }
} as lookup_response %}
{% assign lookup_json = lookup_response | json %}
{% if lookup_response.status != 200 %}
{
  "ok": false,
  "found": false,
  "code": {{ discount_code | json }},
  "message": "Unable to lookup discount code."
}
{% elsif lookup_json contains '"errors"' %}
{
  "ok": false,
  "found": false,
  "code": {{ discount_code | json }},
  "message": "Shopify returned an error while looking up the discount code.",
  "errors": {{ lookup_response.data.errors | json }}
}
{% elsif lookup_json contains '"codeDiscountNodeByCode"' %}
{% assign discount_node = lookup_response.data.data.codeDiscountNodeByCode %}
{% if discount_node == nil %}
{
  "ok": true,
  "found": false,
  "code": {{ discount_code | json }},
  "message": "No discount code was found for {{ discount_code }}."
}
{% else %}
{% assign discount = discount_node.codeDiscount %}
{% assign discount_json = discount | json %}
{% assign value_summary = discount.summary | default: '' %}
{% if discount_json contains '"shortSummary"' %}
  {% assign short_summary = discount.shortSummary | default: '' %}
  {% if short_summary != '' %}
    {% assign value_summary = short_summary %}
  {% endif %}
{% endif %}
{% assign minimum_requirement = 'None' %}
{% if discount_json contains '"greaterThanOrEqualToSubtotal"' %}
  {% assign minimum_subtotal = discount.minimumRequirement.greaterThanOrEqualToSubtotal %}
  {% capture minimum_requirement %}Minimum subtotal {{ minimum_subtotal.amount }} {{ minimum_subtotal.currencyCode }}{% endcapture %}
{% elsif discount_json contains '"greaterThanOrEqualToQuantity"' %}
  {% assign minimum_quantity = discount.minimumRequirement.greaterThanOrEqualToQuantity %}
  {% capture minimum_requirement %}Minimum quantity {{ minimum_quantity }}{% endcapture %}
{% endif %}
{
  "ok": true,
  "found": true,
  "code": {{ discount_code | json }},
  "title": {{ discount.title | json }},
  "type": {{ discount.__typename | json }},
  "status": {{ discount.status | json }},
  "startsAt": {{ discount.startsAt | json }},
  "endsAt": {{ discount.endsAt | json }},
  "usageLimit": {{ discount.usageLimit | json }},
  "usageCount": {{ discount.asyncUsageCount | json }},
  "valueSummary": {{ value_summary | strip | json }},
  "minimumRequirement": {{ minimum_requirement | strip | json }},
  "appliesToAllItems": {% if discount_json contains '"allItems":true' %}true{% else %}false{% endif %},
  "eligibleProducts": [
    {% if discount_json contains '"products"' %}
      {% for product in discount.customerGets.items.products.nodes %}
        {% assign product_url = product.onlineStoreUrl | default: '' %}
        {% if product_url == '' %}
          {% capture product_url %}/products/{{ product.handle }}{% endcapture %}
        {% endif %}
        {% if forloop.first == false %},{% endif %}
        {
          "id": {{ product.id | json }},
          "title": {{ product.title | json }},
          "handle": {{ product.handle | json }},
          "url": {{ product_url | strip | json }}
        }
      {% endfor %}
    {% endif %}
  ],
  "eligibleCollections": [
    {% if discount_json contains '"collections"' %}
      {% for collection in discount.customerGets.items.collections.nodes %}
        {% if forloop.first == false %},{% endif %}
        {
          "id": {{ collection.id | json }},
          "title": {{ collection.title | json }},
          "handle": {{ collection.handle | json }}
        }
      {% endfor %}
    {% endif %}
  ],
  "rawType": {{ discount.__typename | json }},
  "details": {{ discount | json }}
}
{% endif %}
{% else %}
{
  "ok": false,
  "found": false,
  "code": {{ discount_code | json }},
  "message": "Unable to lookup discount code."
}
{% endif %}
{% endif %}
